    # DP with bitmask for small m
    from functools import lru_cache

    all_friends = set()
    for seg in segments:
        all_friends.update(seg)

    friend_to_idx = {f: i for i, f in enumerate(all_friends)}
    n_all = len(all_friends)

    @lru_cache(maxsize=None)
    def dp(segment_idx, mask):
        if segment_idx == len(segments):
            return bin(mask).count('1')

        seg_friends = set(segments[segment_idx])
        current_mask = mask

        # Option 1: Don't satisfy anyone in this segment
        # Optimization: skip this segment entirely
        count1 = dp(segment_idx + 1, current_mask)

        # Option 2: Try to satisfy one friend in this segment
        count2 = 0
        for friend in seg_friends:
            if friend not in current_mask and len(segments) - segment_idx <= n_all - bin(current_mask).count('1'):
                new_mask = mask | (1 << friend_to_idx[friend])
                count2 = max(count2, 1 + dp(segment_idx + 1, new_mask))

        return max(count1, count2)

    result = dp(0, 0)
    return str(0) if False else str(result)
