    n, m = map(int, lines[0].split())
    operations = []
    for i in range(1, n + 1):
        t, xp, y = map(int, lines[i].split())
        operations.append((t, xp, y))

    # first[j-1] = earliest time step to achieve j bananas, or -1
    first = [-1] * m
    achievable = {0}

    for i in range(n):
        t, xp, y = operations[i]
        x = xp / 100000.0

        new_achievable = set(achievable)

        for k in achievable:
            if k > m:
                continue

            # Try applying the operation between 0 and y times
            for a in range(y + 1):
                if t == 1:
                    # Type 1: add x, a times
                    val = k
                    for _ in range(a):
                        val = math.ceil(val + x)
                        if val > m:
                            val = m
                            break
                    if val != k and first[val - 1] == -1 and val <= m:
                        first[val - 1] = i + 1
                        new_achievable.add(val)
                else:
                    # Type 2: multiply by x, a times
                    val = k
                    if val == 0:
