        graph[u].append(v)
        graph[v].append(u)
        edge_idx[i] = (u, v)

    visited = [False] * (n + 1)
    tin = [0] * (n + 1)
    low = [0] * (n + 1)
    timer = [0]
    bridge = [False] * m

    def dfs(node, parent=-1):
        visited[node] = True
        tin[node] = low[node] = timer[0]
        timer[0] += 1

        for next_node in graph[node]:
            if next_node == parent:
                continue
            if visited[next_node]:
                low[node] = min(low[node], tin[next_node])
            else:
                idx = None
                for i, (u, v) in enumerate(edge_idx):
                    if (u == node and v == next_node) or (u == next_node and v == node):
                        idx = i
                        break
                if idx is not None:
                    dfs(next_node, node)
                    low[node] = min(low[node], low[next_node])
                    if low[next_node] > tin[node]:
                        bridge[idx] = True

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i)

    if any(bridge):
        return "0\n"

    # Build orientation
    visited = [False] * (n + 1)
    tin = [0] * (n + 1)
    low = [0] * (n + 1)
    timer = [0]

    order = []

    def dfs_orient(node, parent=-1):
        visited[node] = True
        tin[node] = low[node] = timer[0]
        timer[0] += 1
        order.append(node)

        for next_node in graph[node]:
            if next_node == parent:
                continue
            if visited[next_node]:
                low[node] = min(low[node], tin[next_node])
            else:
                for i, (u, v) in enumerate(edge_idx):
                    if (u == node and v == next_node) or (u == next_node and v == node):
                        # Orient towards the node we first discovered
                        if visited[next_node]:
                            # Back edge
                            if i > 0:
                                u, v = edge_idx[i]
                                if u == next_node:
                                    pass
                                else:
                                    pass
                for i, (u, v) in enumerate(edge_idx):
