    res = [[] for _ in range(n + 1)]
    for i in range(1, n + 1):
        if not visited[i]:
            dfs_orient(i)

    # Rebuild: orient tree edges bottom-up
    # Actually simpler: for tree edges, orient from parent to child
    # For back edges, orient appropriately

    visited = [False] * (n + 1)
    tin = [0] * (n + 1)
    low = [0] * (n + 1)
    timer = [0]
    dfs_order = []
    parent_edge = {}

    def dfs_orient(node, p=-1):
        visited[node] = True
        tin[node] = low[node] = timer[0]
        timer[0] += 1
        dfs_order.append((node, p))

        for next_node in graph[node]:
            if next_node == p:
                continue
            if visited[next_node]:
                low[node] = min(low[node], tin[next_node])
            else:
                dfs_orient(next_node, node)
                low[node] = min(low[node], low[next_node])

    for i in range(1, n + 1):
        if not visited[i]:
            dfs_orient(i)

    # Now orient: tree edges parent -> child, back edges can go either way
    # We need to check which are back edges

    used = [False] * m
    result = []

    for node, p in dfs_order:
        for next_node in graph[node]:
            if next_node == p:
                continue
            # Find edge index
            ei = None
            for i, (u, v) in enumerate(edges):
                if (u == node and v == next_node) or (u == next_node and v == node):
                    ei = i
                    break
            if ei is not None and not used[ei]:
                # Check if tree edge (p is parent)
                if next_node in parent_edge.get(node, {}):
                    used[ei] = True
                    if node < next_node:
                        result.append(f"{node} {next_node}")
                    else:
                        result.append(f"{next_node} {node}")
                # Back edge - orient from larger tin to smaller tin
                elif tin[next_node] < tin[node]:
                    used[ei] = True
                    result.append(f"{next_node} {node}")

    # Check all edges oriented
    oriented = [False] * m
    for line in result:
