            for i, (a, b) in enumerate(edges):
                if (u == a and v == b) or (u == b and v == a):
                    oriented[i] = True
                    break

    if all(oriented):
        return "\n".join(result) + "\n"

    # Fallback: return 0 if any issue (shouldn't happen if no bridges)
    return "0\n"

