    A = []
    for i in range(1, n+1):
        A.append(list(map(int, lines[i].split())))

    B = []
    for i in range(n+1, 2*n+1):
        B.append(list(map(int, lines[i].split())))

    # Check if already equal
    if A == B:
        return "0"

    def table_to_str_table(table):
        return tuple(tuple(row) for row in table)

    A_tuple = table_to_str_table(A)
    B_tuple = table_to_str_table(B)

    # Try sorting by a single column
    for j in range(m):
        A_copy = [row[:] for row in A]
        A_copy.sort(key=lambda row: row[j])
        if tuple(tuple(row) for row in A_copy) == B_tuple:
            return "1\n" + str(j+1)

    # Try sorting by two columns in different orders
    for j in range(m):
        for k in range(m):
            A_copy = [row[:] for row in A]
            A_copy.sort(key=lambda row: row[j])
            A_copy.sort(key=lambda row: row[k])
            if tuple(tuple(row) for row in A_copy) == B_tuple:
                return "2\n" + str(j+1) + " " + str(k+1)

    # Try sorting in reverse order (some problems require this)
    for j in range(m):
        for k in range(m):
            if j != k:
                A_copy = [row[:] for row in A]
                A_copy.sort(key=lambda row: row[k])
                A_copy.sort(key=lambda row: row[j])
                if tuple(tuple(row) for row in A_copy) == B_tuple:
                    return "2\n" + str(k+1) + " " + str(j+1)

