import math
import random

def dist_sq(a, b):
    return (a[0]-b[0])**2 + (a[1]-b[1])**2 + (a[2]-b[2])**2

def dist(a, b):
    return math.sqrt(dist_sq(a, b))

def sphere_from_1(p):
    return p, 0.0

def sphere_from_2(p1, p2):
    center = [(p1[i] + p2[i]) / 2.0 for i in range(3)]
    r = dist(center, p1)
    return center, r

def sphere_from_3(p1, p2, p3):
    # Find circumcenter of 3 points using linear algebra
    # Solve: |x - p1|^2 = |x - p2|^2 and |x - p1|^2 = |x - p3|^2
    A = [
        [p1[0]-p2[0], p1[1]-p2[1], p1[2]-p2[2]],
        [p1[0]-p3[0], p1[1]-p3[1], p1[2]-p3[2]]
    ]
    b = [
        (dist_sq(p1, p2) - dist_sq(p2, p2)) / 2,
        (dist_sq(p1, p3) - dist_sq(p3, p3)) / 2
    ]

    # Convert to 3x3 by adding constraint: solve using pseudo-inverse or all three equations
    # Actually, use all 3 pairwise constraints
    A = [
        [p1[0]-p2[0], p1[1]-p2[1], p1[2]-p2[2]],
        [p1[0]-p3[0], p1[1]-p3[1], p1[2]-p3[2]],
        [p2[0]-p3[0], p2[1]-p3[1], p2[2]-p3[2]]
    ]
    b = [
        dist_sq(p1, p2) / 2 - dist_sq(p2, p2) / 2,
        dist_sq(p1, p3) / 2 - dist_sq(p3, p3) / 2,
        dist_sq(p2, p3) / 2 - dist_sq(p3, p3) / 2
    ]

    try:
        import numpy as np
        center = np.linalg.lstsq(A, b, rcond=None)[0]
    except:
        center = [0.0, 0.0, 0.0]

    # Check for numerical issues
    if any(math.isnan(c) or math.isinf(c) for c in center):
        return [0.0, 0.0, 0.0], 0.0

    r = dist(center, p1)
    return list(center), r

def sphere_from_4(p1, p2, p3, p4):
    # Find circumsphere of 4 points (tetrahedron)
    # |x - pi|^2 = R^2 for i=1,2,3,4
    A = [
        [p1[0]-p2[0], p1[1]-p2[1], p1[2]-p2[2]],
        [p1[0]-p3[0], p1[1]-p3[1], p1[2]-p3[2]],
        [p2[0]-p3[0], p2[1]-p3[1], p2[2]-p3[2]]
    ]
    A.append([p3[0]-p4[0], p3[1]-p4[1], p3[2]-p4[2]])

    b = [
        dist_sq(p1, p2) / 2 - dist_sq(p2, p2) / 2,
        dist_sq(p1, p3) / 2 - dist_sq(p3, p3) / 2,
        dist_sq(p2, p3) / 2 - dist_sq(p3, p3) / 2,
        dist_sq(p3, p4) / 2 - dist_sq(p4, p4) / 2
    ]

    try:
