Looking at this problem, I need to find for each non-MST edge what's the maximum energy value it can have while still potentially being included in some MST. This is a classic MST path-maximum query problem.

The key insight is:
- A non-MST edge c = (u,v) can enter the MST if its weight is less than or equal to the maximum weight edge on the path between u and v in the MST
- E_max(c) = max_weight_on_path(u,v) in MST (the edge would replace this bottleneck)

I'll implement Kruskal's algorithm to find the MST, then use binary lifting with LCA to efficiently query the maximum edge weight on any path in the MST.

```python
import sys

def solution(input_str: str) -> str:
    input_str = input_str.strip()
    if not input_str:
        return ''

    lines = input_str.split('\n')
    n, m = map(int, lines[0].split())

    if m == n - 1:
        return ''

    edges = []
    for i in range(m):
        parts = lines[i + 1].split()
        edges.append((int(parts[0]), int(parts[1]), int(parts[2]), i))

    # Union-Find for MST construction
    parent_parent = list(range(n + 1))
    def find(x):
        if parent_parent[x] == x:
            return x
        parent_parent[x] = find(parent_parent[x])
        return parent_parent[x]

    def union(x, y):
        rx = find(x)
        ry = find(y)
        if rx != ry:
            parent_parent[rx] = ry
            return True
        return False

    # Build MST
    in_mst = [False] * m
    mst_adj = [[] for _ in range(n + 1)]
    edge_weight = [0] * (n + 1)

    for u, v, w, idx in edges:
        if union(u, v):
            in_mst[idx] = True
            mst_adj[u].append((v, w))
            mst_adj[v].append((u, w))

    # BFS for depth, parent, and edge weight to parent
    depth = [0] * (n + 1)
    par = [0] * (n + 1)
    weight_to_parent = [0] * (n + 1)

    # Using iterative DFS to avoid recursion issues
    stack = [1]
    visited = [False] * (n + 1)
    visited[1] = True
    parent_list = [0] * (n + 1)  # For parent during DFS

    order = []

    while stack:
        u = stack.pop()
        order.append(u)
        for v, w in mst_adj[u]:
            if not visited[v]:
                visited[v] = True
                parent_list[v] = u
                depth[v] = depth[u] + 1
                weight_to_parent[v] = w
                stack.append(v)

    # Build binary lifting table
    MAX_LOG = 20
    up = [[0] * MAX_LOG for _ in range(n + 1)]
    mx = [[0] * MAX_LOG for _ in range(n + 1)]

    for v in range(1, n + 1):
        up[v][0] = parent_list[v]
        mx[v][0] = weight_to_parent[v]

    for j in range(1, MAX_LOG):
        for i in range(1, n + 1):
            if up[i][j - 1] != 0:
                up[i][j] = up[up[i][j - 1]][j - 1]
                mx[i][j] = max(mx[i][j - 1], mx[up[i][j - 1]][j - 1])

    # LCA function
    def get_lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        for j in range(MAX_LOG - 1, -1, -1):
            if depth[u] - (1 << j) >= depth[v]:
                u = up[u][j]
        if u == v:
            return v
        for j in range(MAX_LOG - 1, -1, -1):
            if up[u][j] != up[v][j]:
                u = up[u][j]
                v = up[v][j]
        return up[u][0]

    def get_max_on_path(u, v):
        if u == v:
            return float('-inf')
        lca = get_lca(u, v)
        res = float('-inf')
        if depth[u] > depth[v]:
            u, v = v, u
        for j in range(MAX_LOG - 1, -1, -1):
            if depth[u] - (1 << j) >= depth[v]:
                res = max(res, mx[u][j])
                u = up[u][j]
        if u == v:
            return res
        for j in range(MAX_LOG - 1, -1, -1):
            if up[u][j] != up[v][j]:
                res = max(res, mx[u][j])
                res = max(res, mx[v][j])
                u = up[u][j]
                v = up[v][j]
        return max(res, mx[u][0], mx[v][0])

    # Process each non-MST edge
    result = []
    for u, v, w, idx in edges:
        if not in_mst[idx]:
            max_w = get_max_on_path(u, v)
            result.append(str(max_w))
        else:
            # Skip MST edges - problem only asks for non-MST edges
            pass

    return '\n'.join(result)
