def solution_impl(input_str):
    input_str = input_str.strip()
    lines = input_str.split('\n')

    if not lines or not lines[0].strip():
        return ""

    t = int(lines[0].strip())
    results = []

    for i in range(1, t + 1):
        if i >= len(lines):
            break
        line = lines[i].strip().split()
        if len(line) < 2:
            continue
        n, k = int(line[0]), int(line[1])

        if k == 0:
            results.append(' '.join(str(j) for j in range(1, n + 1)))
        elif n < 2 * k:
            results.append('-1')
        else:
            # Try cyclic shift: P[i] maps to (p[K] th smallest available)
            # For lexicographically smallest, we greedily pick smallest valid
            available = set(range(1, n + 1))
            result = []
            valid = True

            # Optimization: for position i, we need p such that |p-i| >= k
            # So p <= i-k or p >= i+k
            # Smallest valid p is either the smallest available <= i-k,
            # or smallest available >= i+k

            sorted_available = sorted(available)
            idx = 0

            for pos in range(1, n + 1):
                # Find smallest p in available such that |p - pos| >= k
                chosen = None

                # Check if smallest available satisfies the condition
                if sorted_available[idx]:
                    if sorted_available[idx] <= pos - k:
                        chosen = sorted_available[idx]
                    elif sorted_available[idx] >= pos + k:
                        chosen = sorted_available[idx]
                    elif sorted_available[idx] < pos - k:
                        chosen = sorted_available[idx]
                    else:
                        # Need larger value
                        while idx < len(sorted_available) - 1:
                            idx += 1
                            if sorted_available[idx] >= pos + k:
                                chosen = sorted_available[idx]
                                break
                        if not chosen:
                            # No valid value from sorted_available[idx+1:] either
                            while idx < len(sorted_available):
                                idx += 1
                                if sorted_available[idx:] and sorted_available[idx] >= pos + k:
                                    chosen = sorted_available[idx]
                                    break
                        else:
                            idx = sorted([p for p in sorted_available if p <= pos-k][0]) or idx + 1
                        if not chosen:
                            idx = idx + 1
                            chosen = None

                if chosen is None:
                    # Back up: try again with sorted available
                    for p in sorted_available:
                        if abs(p - pos) >= k:
                            chosen = p
                            break

                if chosen is None:
                    valid = False
                    break

                available.remove(chosen)
                result.append(str(chosen))

            if valid:
                results.append(' '.join(result))
            else:
                results.append('-1')

    return '\n'.join(results)
