            for p in range(1, n + 1):
                if used[p]:
                    continue
                if abs(p - pos) < k:
                    continue
                if p < best_p:
                    best_p = p

            if best_p == float('inf'):
                valid = False
                break

            result[pos - 1] = best_p
            used[best_p] = True

        if not valid:
            results.append('-1')
        else:
            results.append(' '.join(str(x) for x in result))

