def solution(input_str):
    """
    Find a subset of employees to attend the party such that Igor loses.
    Igor loses if at least one employee receives a different number of messages
    than he predicted.
    """
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    adj = []  # adjacency matrix: adj[i][j] = 1 if employee i+1 contacts j+1
    for i in range(n):
        row = lines[i + 1]
        adj.append([int(c) for c in row])

    targets = list(map(int, lines[-1].split()))`

    def compute_counts(mask):
        """Compute message counts for given subset (represented by bitmask)"""
        counts = [0] * n
        for sender in range(n):
            if (mask >> sender) & 1:
                for j in range(n):
                    if adj[sender][j] == 1:
                        counts[j] += 1
        return counts

    def check(mask):
        """Check if at least one person has different count than predicted"""
        counts = compute_counts(mask)
        for i in range(n):
            if counts[i] != targets[i]:
                return True
        return False

    # Try empty subset first
    if check(0):
        result = []
        return f"{' '.join(map(str, result))}"

    # For n small enough, brute force all subsets
    # For n up to ~20, 2^20 = 1M which is acceptable

    # Try increasing subset sizes
    from itertools import combinations

    for k in range(1, n + 1):
        indices = list(range(n))
        for combo in combinations(indices, k):
            mask = 0
            for i in combo:
                mask |= (1 << i)
            if check(mask):
                result = [str(i + 1) for i in combo]
                return f"{k}\n"

    # Return -1 if no subset works
    return "-1"

